<section class="content-card-list member-admin-list <?=$registrationMode?'registration-admin-list':''?>"><?php foreach($members as $m):$payload=e(json_encode(['id'=>$m['id'],'name'=>$m['name'],'username'=>$m['username']??'','email'=>$m['email'],'mobile'=>$m['mobile'],'member_number'=>$m['member_number'],'joined_at'=>$m['joined_at'],'status'=>$m['status'],'address'=>$m['address'],'role_title'=>$m['role_title'],'bio'=>$m['bio'],'date_of_birth'=>$m['date_of_birth']??'','nic_number'=>$m['nic_number']??'','gender'=>strtolower((string)($m['gender']??'')),'is_public'=>(int)$m['is_public']],JSON_HEX_APOS|JSON_HEX_QUOT));?><article class="admin-panel member-card premium-member-admin-card"><div class="member-card-head"><div class="table-person"><?php $logo=setting('foundation','logo_path','');$logoEnabled=setting('foundation','logo_enabled','1')==='1'; if($m['profile_photo']):?><img src="<?=e(public_upload($m['profile_photo']))?>" alt=""><?php elseif($logoEnabled&&$logo):?><span class="brand-avatar-fallback"><img src="<?=e(public_upload($logo))?>" alt="Foundation logo"></span><?php else:?><span><?=e(strtoupper(substr($m['name'],0,1)))?></span><?php endif;?><div><h3><?=e($m['name'])?></h3><small>@<?=e($m['username']?:'no-username')?> · <?=e($m['email'])?></small></div></div><div class="state-badges"><span class="status-badge <?=e($m['status'])?>"><?=e(ucfirst($m['status']))?></span><span class="member-public-state <?=((int)$m['is_public']===1&&$m['status']==='active')?'published':'private'?>"><?=((int)$m['is_public']===1&&$m['status']==='active')?'Published':'Private'?></span></div></div><div class="member-meta"><p><small>Member ID</small><b><?=e($m['member_number']?:'—')?></b></p><p><small>NIC / National ID</small><b><?=e($m['nic_number']?:'—')?></b></p><p><small>Contact</small><b><?=e($m['mobile']?:'—')?></b></p><p><small>Joined</small><b><?=e($m['joined_at']?date('d M Y',strtotime($m['joined_at'])):'—')?></b></p></div><?php if($m['status']==='rejected'&&!empty($m['rejection_reason'])):?><div class="member-rejection-note"><b>Rejection reason</b><span><?=e($m['rejection_reason'])?></span></div><?php endif;?><div class="card-admin-actions"><a class="outline-link" href="<?=url('admin/members/view/'.$m['id'])?>">View / QR</a><?php if(!$registrationMode):?><button class="outline-link" type="button" data-member-edit='<?=$payload?>'>✎ Edit</button><?php endif;?><?php if($m['status']!=='active'):?><form method="post" action="<?=url('admin/members/status')?>"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="status" value="active"><button class="admin-btn mini-action"><?=$m['status']==='pending'?'Approve & Publish':'Activate & Publish'?></button></form><?php endif;?><?php if($m['status']==='pending'):?><form method="post" action="<?=url('admin/members/status')?>" class="reject-inline"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="status" value="rejected"><input name="reason" maxlength="500" placeholder="Reason (optional)"><button class="danger-link">Reject</button></form><?php endif;?><?php if($user['role']==='super_admin'):?><form method="post" action="<?=url('admin/members/delete')?>" data-confirm="Permanently delete this member account?"><?=csrf_field()?><input type="hidden" name="id" value="<?=$m['id']?>"><button class="danger-link">Delete</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$members):?><div class="admin-panel empty-card">No matching members found.</div><?php endif;?><?=admin_pagination($pagination??[])?></section></div>